/**
 * Returns whether the report action is a thread reply and its parent message has been deleted.
 */
function isReportActionOrphan(reportAction: OnyxEntry<ReportAction>, parentReportActions: OnyxEntry<ReportActions>): boolean {
    if (!reportAction || !parentReportActions || !reportAction.parentReportActionID) {
        return false;
    }

    const parentReportAction = parentReportActions[reportAction.parentReportActionID];
    if (parentReportAction) {
        return false;
    }

    // If the parent action is not in the collection, we need to check if it's pending deletion.
    // This can happen if the parent message is deleted offline.
    const parentReportActionFromOnyx = allReportActions?.[`${ONYXKEYS.COLLECTION.REPORT_ACTIONS}${reportAction.reportID}`]?.[reportAction.parentReportActionID];
    if (parentReportActionFromOnyx) {
        return false;
    }

    return true;
}

