/**
 * Returns whether the report action is a thread reply and its parent message has been deleted.
 */
function isReportActionOrphan(reportAction: OnyxEntry<ReportAction>): boolean {
    if (!reportAction || !reportAction.parentReportActionID) {
        return false;
    }

    const parentReportActions = allReportActions?.[`${ONYXKEYS.COLLECTION.REPORT_ACTIONS}${reportAction.reportID}`];
    if (parentReportActions && parentReportActions[reportAction.parentReportActionID]) {
        return false;
    }

    return true;
}

